class Node<T>(val value: T, var next: Node<T>? = null, var prev: Node<T>? = null)

class DoublyLinkedList<T> {
    var head: Node<T>? = null
    fun prepend(value: T) {
        val n = Node(value, next = head)
        head?.prev = n
        head = n
    }
}

fun search(root: TreeNode?, key: Int): Boolean = when {
    root == null -> false
    root.value == key -> true
    key < root.value -> search(root.left, key)
    else -> search(root.right, key)
}

class TrieNode(val children: MutableMap<Char, TrieNode> = mutableMapOf(),
               var isWord: Boolean = false)
class Trie {
    val root = TrieNode()
    fun insert(word: String) {
        var node = root
        for (c in word) node = node.children.getOrPut(c) { TrieNode() }
        node.isWord = true
    }
}

