// Fibonacci - naive recursion is O(2^n)
fun fibNaive(n: Int): Int = if (n < 2) n else fibNaive(n - 1) + fibNaive(n - 2)

// Memoized top-down DP is O(n)
val memo = mutableMapOf<Int, Long>()
fun fibMemo(n: Int): Long =
    memo.getOrPut(n) { if (n < 2) n.toLong() else fibMemo(n - 1) + fibMemo(n - 2) }

