// Retry with backoff
suspend fun <T> retryWithBackoff(
    times: Int = 3,
    initialDelay: Long = 1000,
    factor: Double = 2.0,
    block: suspend () -> T
): T {
    var currentDelay = initialDelay
    repeat(times - 1) {
        try { return block() } catch (e: Exception) { /* ... */ }
        delay(currentDelay)
        currentDelay = (currentDelay * factor).toLong()
    }
    return block()
}

