class UserRepository(
    private val api: UserApi,
    private val dao: UserDao
) {
    // Room's DAO flow re-emits whenever the table changes, so it never completes:
    // do NOT wrap it in emitAll(...) followed by sync code, that code would never run.
    fun getUsers(): Flow<List<User>> =
        dao.getUsers().onStart { syncWithRemote() } // reflect cached data, then refresh

    private suspend fun syncWithRemote() {
        try {
            val remoteUsers = api.getUsers()
            dao.insertAll(remoteUsers) // DB update makes the DAO flow re-emit
        } catch (e: Exception) {
            // Handle offline or error; cached data is still served
        }
    }
}

