class TieredCache(private val mem: LruCache<String, Any>) {
    suspend fun <T> get(key: String, fetch: suspend () -> T): T {
        mem.get(key)?.let { return it as T }
        return fetch().also { mem.put(key, it) } // promote on miss
    }
    fun invalidate(key: String) { mem.remove(key) }
}

fun lengthOfLongestSubstring(s: String): Int {
    val seen = mutableSetOf<Char>()
    var left = 0
    var best = 0
    for ((right, c) in s.withIndex()) {
        while (c in seen) seen.remove(s[left++])
        seen.add(c)
        best = maxOf(best, right - left + 1)
    }
    return best
}
